#!/usr/bin/env node
/**
 * Bundles the Chrome extension's blocker (page-hook.js + content.js + content.css) into the
 * TypeScript module the iPhone/Android app injects into its WebView:
 *   mobile-app/src/blocker/blockerScript.generated.ts
 *
 * The generated file is committed, so the app builds on EAS without anything outside mobile-app/.
 * Run this after changing any of the three source files:
 *   node scripts/build-app-blocker.js          write the module
 *   node scripts/build-app-blocker.js --check  exit 1 if the committed module is out of date
 */
'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SOURCE_DIR = path.join(ROOT, 'chrome-extension');
const OUTPUT = path.join(ROOT, 'mobile-app', 'src', 'blocker', 'blockerScript.generated.ts');

function readSource(name) {
  return fs.readFileSync(path.join(SOURCE_DIR, name), 'utf8').replace(/\r\n/g, '\n').trimEnd();
}

function toStringLiteral(text) {
  return JSON.stringify(text)
    .split(String.fromCharCode(0x2028)).join('\\u2028')
    .split(String.fromCharCode(0x2029)).join('\\u2029');
}

/** The exact script the WebView runs at document start in every main-frame document. */
function buildScript() {
  return [
    '/* AntiShort blocker for the iPhone/Android app WebView.',
    ' * Built by scripts/build-app-blocker.js from chrome-extension/page-hook.js, content.js and content.css. */',
    '(function () {',
    "  'use strict';",
    '  // Injected into every main-frame document; returns immediately unless the host serves Shorts.',
    '  var host = String(location.hostname).toLowerCase();',
    "  if (host !== 'youtube.com' && host !== 'www.youtube.com' && host !== 'm.youtube.com') return;",
    '  var ANTISHORT_INJECT_CSS = ' + toStringLiteral(readSource('content.css')) + ';',
    readSource('page-hook.js'),
    readSource('content.js'),
    '})();',
    'true;',
    ''
  ].join('\n');
}

function buildModule() {
  const script = buildScript();
  const sha256 = crypto.createHash('sha256').update(script, 'utf8').digest('hex');
  return [
    '// AUTO-GENERATED by scripts/build-app-blocker.js. Do not edit by hand.',
    '// Sources: chrome-extension/page-hook.js, chrome-extension/content.js, chrome-extension/content.css',
    '// Regenerate from the repository root: node scripts/build-app-blocker.js',
    '',
    `export const BLOCKER_SCRIPT_SHA256 = '${sha256}';`,
    '',
    `export const BLOCKER_SCRIPT: string = ${toStringLiteral(script)};`,
    ''
  ].join('\n');
}

function isUpToDate() {
  if (!fs.existsSync(OUTPUT)) return false;
  return fs.readFileSync(OUTPUT, 'utf8').replace(/\r\n/g, '\n') === buildModule();
}

module.exports = { buildScript, buildModule, isUpToDate, OUTPUT };

if (require.main === module) {
  const relative = path.relative(ROOT, OUTPUT);
  if (process.argv.includes('--check')) {
    if (!isUpToDate()) {
      console.error(`${relative} is out of date. Run: node scripts/build-app-blocker.js`);
      process.exit(1);
    }
    console.log(`${relative} is up to date.`);
  } else {
    fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
    fs.writeFileSync(OUTPUT, buildModule());
    console.log(`Wrote ${relative} (${buildScript().length} characters of injected script).`);
  }
}
